const FOLDER_NAMES_OPEN: Record<string, string> = {
};

const icon = (id: string): SymbolIcon => ({ char: String.fromCodePoint(ICONS[id][0]), color: ICONS[id][1] });
const icons = (ids: Record<string, string>): Record<string, SymbolIcon> => Object.fromEntries(Object.entries(ids).map(([key, id]) => [key, icon(id)]));

export const file = icon("document");
export const folder = icon("folder");
export const folderOpen = icon("folder");
export const byFileName = icons(FILE_NAMES);
export const byExtension = icons(EXTENSIONS);
export const byFolderName = icons(FOLDER_NAMES);
export const byFolderNameOpen = icons(FOLDER_NAMES_OPEN);

/** The Symbols icon of a file or folder named `name` (no path): exact name, longest extension, default. */
export function symbolIcon(name: string, { isDirectory = false, open = false } = {}): SymbolIcon {
	const lower = String(name).toLowerCase();
	if (isDirectory) return (open && byFolderNameOpen[lower]) || byFolderName[lower] || (open ? folderOpen : folder);
	if (byFileName[lower]) return byFileName[lower];
	// "a.test.ts" tries "test.ts", then "ts"; ".eslintrc.json" tries "eslintrc.json", then "json".
	for (let dot = lower.indexOf("."); dot >= 0; dot = lower.indexOf(".", dot + 1)) {
		const found = byExtension[lower.slice(dot + 1)];
		if (found) return found;
	}
	return file;
}
